import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"RLHF (Bridge)","description":"Engineering-decision bridge for RLHF: where model behavior and alignment come from, and why app engineers only need to understand it, never implement it.","frontmatter":{"title":"RLHF (Bridge)","description":"Engineering-decision bridge for RLHF: where model behavior and alignment come from, and why app engineers only need to understand it, never implement it.","domain":"tech","tags":["tech","training","bridge","rlhf"],"navOrder":142,"topicId":"model-lifecycle-rlhf","layer":"1","status":"bridge","nodeType":"boundary","owner":"learn-ai","externalOwners":[{"site":"llm","url":"https://llm.zenheart.site/"}],"lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"tech/01-model-lifecycle/post-training/rlhf.md","filePath":"tech/01-model-lifecycle/post-training/rlhf.md","lastUpdated":1788326832000}'),i={name:"tech/01-model-lifecycle/post-training/rlhf.md"};function o(s,e,l,d,h,m){return a(),r("div",null,[...e[0]||(e[0]=[n('<blockquote><p><strong>Group</strong>: Model Lifecycle (bridge) | <strong>Previous group exit</strong>: inference fundamentals and interface contracts | <strong>This page exit</strong>: know when to change weights instead of prompts or retrieval</p></blockquote><h1 id="rlhf-bridge" tabindex="-1">RLHF (Bridge) <a class="header-anchor" href="#rlhf-bridge" aria-label="Permalink to &quot;RLHF (Bridge)&quot;">​</a></h1><blockquote><p><strong>Bridge page</strong>: this page answers only &quot;how RLHF affects your application engineering decisions&quot;. Reward modeling and PPO/DPO mechanics are derived in <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a> (RLHF/DPO chapters).</p></blockquote><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><p><strong>Reinforcement Learning from Human Feedback (RLHF)</strong>: humans rank multiple model outputs, a reward model is trained to predict those preferences, and reinforcement learning then optimizes the model to maximize the reward score. It changes not what the model <em>knows</em> (that is pretraining and SFT) but how it <em>behaves</em> — the helpful/honest/harmless alignment behavior comes mainly from this stage.</p><p>Three steps:</p><ol><li><strong>SFT</strong>: base capability from human demonstrations.</li><li><strong>Reward modeling</strong>: human rankings → train a reward model that predicts preference.</li><li><strong>RL</strong>: optimize outputs to maximize reward (PPO, or direct-alignment variants such as Direct Preference Optimization).</li></ol><h2 id="why-app-engineers-understand-it-but-never-implement-it" tabindex="-1">Why app engineers understand it but never implement it <a class="header-anchor" href="#why-app-engineers-understand-it-but-never-implement-it" aria-label="Permalink to &quot;Why app engineers understand it but never implement it&quot;">​</a></h2><p>RLHF requires large-scale human feedback data, a dedicated research team, and substantial training compute. This is the work model vendors (OpenAI, Anthropic, Google, Meta, ...) do when producing the models you consume via API. &quot;Run RLHF ourselves&quot; is not an option in your engineering decisions — when the need is behavioral, check the mainline toolbox first:</p><ul><li>Fixed tone/format → <a href="./../../03-context/prompt.html">prompt engineering</a> + few-shot examples.</li><li>Domain knowledge → <a href="./../../04-grounding/rag.html">RAG</a>.</li><li>Refusing certain requests → input validation + output filtering (application security, see <a href="./../../08-production/security.html">Security</a>).</li></ul><h2 id="model-behavior-that-understanding-rlhf-explains" tabindex="-1">Model behavior that understanding RLHF explains <a class="header-anchor" href="#model-behavior-that-understanding-rlhf-explains" aria-label="Permalink to &quot;Model behavior that understanding RLHF explains&quot;">​</a></h2><p>That is the real value of this page — three common &quot;why does the model do that&quot; cases:</p><ol><li><strong>Over-refusal</strong>: alignment training amplifies boundaries; the model rejects some benign requests. Product-side response: let the user clarify and retry instead of treating refusal as terminal.</li><li><strong>Verbosity and hedging</strong>: &quot;As an AI language model...&quot; preambles. Product-side response: constrain output shape in the prompt, combined with <a href="./../../02-inference-interface/structured-output.html">structured output</a>.</li><li><strong>Model &quot;personality&quot;</strong>: style differences across vendors come mainly from preference-data choices at the alignment stage. Treat &quot;does the personality match the product voice&quot; as a selection criterion — see <a href="./../../08-production/evaluation.html">Evaluation (bridge)</a>.</li></ol><h2 id="decision-impact-table" tabindex="-1">Decision impact table <a class="header-anchor" href="#decision-impact-table" aria-label="Permalink to &quot;Decision impact table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Data requirement</strong></td><td>Large-scale human preference rankings (vendor-level investment; app teams do not have this)</td></tr><tr><td><strong>Cost structure</strong></td><td>Research-grade: feedback collection + multi-round training + evaluation (no specific figures cited here)</td></tr><tr><td><strong>Time to effect</strong></td><td>Model-version granularity — you only &quot;use&quot; a new alignment by switching model/version</td></tr><tr><td><strong>Maintenance burden</strong></td><td>The vendor&#39;s burden; yours is behavior regression testing after model-version upgrades</td></tr></tbody></table><h2 id="division-of-labor-sft-vs-rlhf" tabindex="-1">Division of labor: SFT vs RLHF <a class="header-anchor" href="#division-of-labor-sft-vs-rlhf" aria-label="Permalink to &quot;Division of labor: SFT vs RLHF&quot;">​</a></h2><p>Both bridges in one table, to defuse the &quot;it&#39;s all training&quot; confusion:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Owner</th><th>What changes</th><th>Your involvement</th></tr></thead><tbody><tr><td>The model doesn&#39;t know my domain/format</td><td><a href="./sft.html">SFT</a></td><td>Knowledge and skill (weights)</td><td>A real project once data and budget exist</td></tr><tr><td>The model&#39;s behavior is wrong (tone, refusal, verbosity)</td><td>RLHF / alignment</td><td>Behavioral preference (weights)</td><td>Never a project — adapt via model selection and prompts</td></tr><tr><td>The model lacks live/private facts</td><td><a href="./../../04-grounding/rag.html">RAG</a></td><td>Context (weights unchanged)</td><td>Everyday mainline work</td></tr></tbody></table><p>Nearly all flagship chat models go through RLHF or comparable alignment (RLAIF / Constitutional AI and the like); the differences show up mainly as each vendor&#39;s &quot;personality&quot; and safety boundaries — part of selection evaluation.</p><h2 id="deep-derivations-and-implementation" tabindex="-1">Deep derivations and implementation <a class="header-anchor" href="#deep-derivations-and-implementation" aria-label="Permalink to &quot;Deep derivations and implementation&quot;">​</a></h2><ul><li>Reward models, PPO, DPO derivations and comparisons → the RLHF/DPO chapters of <a href="https://llm.zenheart.site/" target="_blank" rel="noreferrer">Learn LLM</a>.</li><li>Further reading (original papers): <a href="https://arxiv.org/abs/2203.02155" target="_blank" rel="noreferrer">InstructGPT</a>, <a href="https://arxiv.org/abs/2212.08073" target="_blank" rel="noreferrer">Constitutional AI</a>, <a href="https://openai.com/research/learning-from-human-preferences" target="_blank" rel="noreferrer">Deep RL from Human Preferences</a>.</li></ul>',21)])])}const b=t(i,[["render",o]]);export{f as __pageData,b as default};
